{
  "findings": [
    {
      "check_id": "CKV_AZURE_112",
      "title": "Ensure that key vault key is backed by HSM",
      "resource": "azurerm_key_vault_key.generated",
      "severity": "MEDIUM",
      "explanation": "The key is not backed by a hardware security module (HSM), which provides stronger security guarantees for cryptographic operations."
    },
    {
      "check_id": "CKV_AZURE_40",
      "title": "Ensure that the expiration date is set on all keys",
      "resource": "azurerm_key_vault_key.generated",
      "severity": "MEDIUM",
      "explanation": "The key does not have an expiration date set, which increases the risk of using outdated or compromised keys indefinitely."
    }
  ],
  "patched_code": "resource \"azurerm_key_vault_key\" \"generated\" {\n  name         = \"terragoat-generated-certificate-${var.environment}\"\n  key_vault_id = azurerm_key_vault.example.id\n  key_type     = \"RSA-HSM\"\n  key_size     = 2048\n  key_opts = [\n    \"decrypt\",\n    \"encrypt\",\n    \"sign\",\n    \"unwrapKey\",\n    \"verify\",\n    \"wrapKey\",\n  ]\n  expiration_date = \"2025-12-31T23:59:59Z\"\n}",
  "fix_summary": "Updated the key type to 'RSA-HSM' to ensure it is backed by a hardware security module (HSM). Added an expiration date to the key to mitigate risks associated with indefinite key usage."
}
